import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Button, Input, FormGroup, Label } from 'reactstrap';

const SendPointsModal = ({ isOpen, toggle, headerId, loginUserId, otherUserId, onSendPoints }) => {
    const [amount, setAmount] = useState('');
    const [appPoints, setAppPoints] = useState(0);
    const [sentPoints, setSentPoints] = useState(0);

    useEffect(() => {
        // Fetch the user's app points
        fetch(`http://localhost:8080/api/users/${loginUserId}`)
            .then((response) => response.json())
            .then((data) => setAppPoints(data.points))
            .catch((error) => console.error('Error fetching app points:', error));

        // Fetch the total sent points for this chat
        fetch(`http://localhost:8080/api/chats/${headerId}/sentPoints`)
            .then((response) => response.json())
            .then((data) => setSentPoints(data.sent_points))
            .catch((error) => console.error('Error fetching sent points:', error));
    }, [headerId, loginUserId]);

    const handleSend = () => {
        onSendPoints(amount);
        setAmount('');
    };

    return (
        <Modal isOpen={isOpen} toggle={toggle}>
            <ModalHeader toggle={toggle}>송금</ModalHeader>
            <ModalBody>
                <FormGroup>
                    <Label for="appPoints">보유 포인트</Label>
                    <Input type="text" id="appPoints" value={appPoints} readOnly />
                </FormGroup>
                <FormGroup>
                    <Label for="sentPoints">보낸 총 금액</Label>
                    <Input type="text" id="sentPoints" value={sentPoints} readOnly />
                </FormGroup>
                <FormGroup>
                    <Label for="amount">송금 금액</Label>
                    <Input
                        type="number"
                        id="amount"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        placeholder="송금할 금액을 입력하세요"
                    />
                </FormGroup>
            </ModalBody>
            <ModalFooter>
                <Button color="primary" onClick={handleSend}>
                    보내기
                </Button>
                <Button color="secondary" onClick={toggle}>
                    취소
                </Button>
            </ModalFooter>
        </Modal>
    );
};

export default SendPointsModal;
